#pragma once
// Generates the NEON TITAN preset library from "recipes".
// Each recipe is a hand-designed sound style with safe ranges for its knobs.
// Variations are made with a fixed random seed, so the library is identical on every computer.
#include <juce_core/juce_core.h>
#include <vector>
#include <tuple>
#include <map>

struct Recipe
{
    const char* category;
    const char* subtype;
    int count;
    std::vector<std::pair<const char*, float>> base;                 // fixed values
    std::vector<std::tuple<const char*, float, float>> ranges;       // random between lo and hi
    std::vector<std::pair<const char*, std::vector<float>>> picks;   // random choice from a list
};

struct GenWords { std::vector<const char*> adj, noun; };

